export type RoomProp = [
  prototype: string,
  x: number,
  y: number,
  z: number,
  yaw: number,
  scale: number,
  grime: number,
];
type Fragment = [
  x: number,
  z: number,
  size: number,
  yaw: number,
  pitch: number,
  roll: number,
  seed: number,
];
export type CounterFootprint = [x: number, z: number, length: number, axis: 'x' | 'z'];
export type RoomFixture =
  | ['prop', ...RoomProp]
  | ['counter', footprint: CounterFootprint, goods: RoomProp[]]
  | ['bench', alongX: boolean, width: number, goods: RoomProp[]]
  | ['shelf', side: number, along: number, height: number, width: number, goods: RoomProp[]]
  | [
      'conduit',
      side: number,
      from: number,
      to: number,
      height: number,
      dropAlong: number,
      boxHeight: number,
      flex: boolean,
    ]
  | [
      'lean',
      side: number,
      along: number,
      tilt: number,
      height: number,
      width: number,
      material: string,
    ]
  | ['joist', x: number, z: number, alongX: boolean, span: number, thickness: number]
  | ['bulb', x: number, z: number, drop: number]
  | [
      'rug',
      material: string,
      x: number,
      z: number,
      width: number,
      depth: number,
      yaw: number,
      seed: number,
    ]
  | ['blanket', seed: number]
  | ['cushion', material: string, x: number, z: number, yaw: number]
  | ['living-drape', near: boolean, seed: number]
  | [
      'wall-drape',
      side: number,
      along: number,
      height: number,
      width: number,
      drop: number,
      material: string,
      seed: number,
    ]
  | ['ruin', x: number, z: number, fragments: Fragment[]]
  | ['ruin-drape', x: number, z: number, yaw: number, seed: number];

